window.docContents[247].resolve({"/#Functional-Programming-in-Lean--Getting-to-Know-Lean--Summary--Strings-and-Slices":{"contents":"Strings are sequences of characters, which are themselves Unicode code points.\nTheir run-time representation consists of an array of bytes in the UTF-8 encoding and a cached character count field.\nBecause Lean is a pure functional language, operations such as trimming whitespace from strings would normally need to copy them.\nThis is avoided by having many functions on strings return string slices, which pair a reference to a string with starting and ending positions.\nSlices can be manipulated by updating these starting and ending positions, avoiding copying.\n\n","context":"Functional Programming in Lean\u0009Getting to Know Lean\u0009Summary","header":"1.9.5. Strings and Slices","id":"/#Functional-Programming-in-Lean--Getting-to-Know-Lean--Summary--Strings-and-Slices"}});